// Selected official application controller; generated by prepare_partner_detail_window_ui.py.
namespace Zjcs.Official.PartnersUI
{
using Object = UnityEngine.Object;
using Zjcs.Official.ProfessionUI;
using Zjcs.Official.WorldUI;
using MultiLanguageText = Zjcs.Official.WorldUI.WorldMultiLanguageText;
using AchievementDataKey = Zjcs.Official.Partners.PartnerFriendshipAchievementRules.AchievementDataKey;
using AchievementDataKeyNpcFriendshipLevel = Zjcs.Official.Partners.PartnerFriendshipAchievementRules.AchievementDataKeyNpcFriendshipLevel;
using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;

public class NpcDetailPanel : UIBase
{
	public enum TabType
	{
		Detail,
		Gift,
		Profile,
		Achievement
	}

	[Serializable]
	public class TabData
	{
		public WorldTabItem TabItem;

		public TabType TabType;
	}

	[SerializeField]
	private NpcDetailPanelPropContent mPropContent;

	[SerializeField]
	private NpcDetailPanelGiftContent mGiftContent;

	[SerializeField]
	private NpcFriendshipLevelContent mFriendshipContent;

	[SerializeField]
	private NpcDetailPanelDetailContent mDetailContent;

	[SerializeField]
	private NpcDetailPanelProfileContent mProfileContent;

	[SerializeField]
	private PartnerAchievementPanel mAchievementPanel;

	[SerializeField]
	private WorldStateSwitcher<TabType> mStateSwitcher;

	[SerializeField]
	private List<TabData> mTabDatas;

	[SerializeField]
	private WorldTabGroup mTabGroup;

	[SerializeField]
	private Button mLeftBtn;

	[SerializeField]
	private Button mRightBtn;

	[SerializeField]
	private Button mFullViewBtn;

	[SerializeField]
	private Button mExitFullViewBtn;

	[SerializeField]
	private WorldStateSwitcher<bool> mFullViewStates;

	[SerializeField]
	private List<TipDotNodeLinker> mTipDotLinkers;

	[SerializeField]
	private NpcTreasureIcon mNpcTreasureIcon;

	public WorldGAction OnChangeNpc = new WorldGAction();

	public WorldGAction OnRefresh = new WorldGAction();

	private int mIndex;

	private PartnerDetailPresentationInfo mNpcInfo;

	private IPartnerDetailWindowNpcData mNpcData;

	private AchievementDataKeyNpcFriendshipLevel mDataKey;

	private List<IPartnerDetailWindowNpcData> mDataWrapList = new List<IPartnerDetailWindowNpcData>();

	private List<AchievementDataKey> mDataKeys = new List<AchievementDataKey>();

	public IPartnerDetailWindowNpcData NpcData => mNpcData;

    private IPartnerDetailWindowServices services;
    public void Configure(IPartnerDetailWindowServices value)
    { services = value ?? throw new ArgumentNullException(nameof(value)); }

	protected override void OnEnableAndInited()
	{








		base.OnEnableAndInited();
		((UnityEvent<WorldTabItem, bool>)mTabGroup.OnTabItemChanged).AddListener((UnityAction<WorldTabItem, bool>)OnTabItemChanged);
		((UnityEvent)mLeftBtn.onClick).AddListener((UnityAction)OnClickLeftBtn);
		((UnityEvent)mRightBtn.onClick).AddListener((UnityAction)OnClickRightBtn);
		((UnityEvent)mFullViewBtn.onClick).AddListener((UnityAction)OnEnterFullView);
		((UnityEvent)mExitFullViewBtn.onClick).AddListener((UnityAction)OnExitFullView);
		services.OnRemoveNpc += MainPlayer_OnRemoveNpc;
		InitContent();
	}

	protected override void OnDisableAndInited()
	{








		((UnityEvent<WorldTabItem, bool>)mTabGroup.OnTabItemChanged).RemoveListener((UnityAction<WorldTabItem, bool>)OnTabItemChanged);
		((UnityEvent)mLeftBtn.onClick).RemoveListener((UnityAction)OnClickLeftBtn);
		((UnityEvent)mRightBtn.onClick).RemoveListener((UnityAction)OnClickRightBtn);
		((UnityEvent)mFullViewBtn.onClick).RemoveListener((UnityAction)OnEnterFullView);
		((UnityEvent)mExitFullViewBtn.onClick).RemoveListener((UnityAction)OnExitFullView);
		if (services != null)
		{
			services.OnRemoveNpc -= MainPlayer_OnRemoveNpc;
		}
		base.OnDisableAndInited();
	}

	public void Init(List<IPartnerDetailWindowNpcData> npcDataWrapList, int index)
	{
		InitWrapper(() =>
		{
			mIndex = index;
			mDataWrapList.Clear();
			mDataWrapList.AddRange(npcDataWrapList);
		});
	}

	private void InitContent()
	{
		((Component)mLeftBtn).gameObject.SetActive(mDataWrapList.Count > 1);
		((Component)mRightBtn).gameObject.SetActive(mDataWrapList.Count > 1);
		mFullViewStates.SetState(state: false);
		mTabGroup.ResetTabItem(needNotify: true);
		Refresh();
		mNpcTreasureIcon.RefleshNpcTreasureInfo(mNpcInfo.Properties.TreasureClassId);
	}

	private void Refresh()
	{
		IPartnerDetailWindowNpcData playerNpcDataWrap = mNpcData;
		mNpcData = services.GetNpcByClassId(mDataWrapList[mIndex].NpcClassId);
		mNpcInfo = services.GetNpcInfo(mNpcData.NpcClassId);
		mDataKey = new AchievementDataKeyNpcFriendshipLevel
		{
			NpcClassId = mNpcData.NpcClassId
		};
		mPropContent.Init(mNpcData, mNpcInfo.Properties);
		mGiftContent.Init(mNpcData, mNpcInfo.Properties.Friendship, null, ResetExpPreview, ShowExpPreview);
		mFriendshipContent.Init(mNpcData, mNpcInfo.Properties.Friendship);
		mDetailContent.Init(mNpcData, mNpcInfo);
		mProfileContent.Init(mNpcData);
		foreach (TipDotNodeLinker mTipDotLinker in mTipDotLinkers)
		{
			mTipDotLinker.SetNodeInstanceInfo(new NpcNodeInstanceInfo(mNpcData.NpcClassId));
		}
		if ((Object)(object)mAchievementPanel != (Object)null)
		{
			mDataKeys.Clear();
			mDataKeys.Add(mDataKey);
			mAchievementPanel.SetDataKey(mDataKey);
		}
		if (playerNpcDataWrap != mNpcData)
		{
			OnChangeNpc?.Invoke();
		}
		OnRefresh?.Invoke();
	}

	private void MainPlayer_OnRemoveNpc(int npcClassId)
	{
		if (mNpcData != null && mNpcData.NpcClassId == npcClassId)
		{
			services.Close(((Component)this).gameObject);
		}
	}

	private void OnTabItemChanged(WorldTabItem tabItem, bool value)
	{
		if (value)
		{
			TabData tabData = GetTabData(tabItem);
			if (tabData != null)
			{
				mStateSwitcher.SetState(tabData.TabType);
			}
		}
	}

	private TabData GetTabData(WorldTabItem tabItem)
	{
		return mTabDatas.Find((TabData data) => (Object)(object)data.TabItem == (Object)(object)tabItem);
	}

	private void GiveGiftCallBack()
	{
		mDetailContent.ShowNpcTalk();
	}

	private void ResetExpPreview()
	{
		mFriendshipContent.ResetExpPreview();
	}

	private void ShowExpPreview(Dictionary<int, long> giftDict)
	{
		mFriendshipContent.ShowExpPreview(giftDict);
	}

	private void OnClickLeftBtn()
	{
		mIndex = (mIndex - 1 + mDataWrapList.Count) % mDataWrapList.Count;
		Refresh();
		mNpcTreasureIcon.RefleshNpcTreasureInfo(mNpcInfo.Properties.TreasureClassId);
	}

	private void OnClickRightBtn()
	{
		mIndex = (mIndex + 1 + mDataWrapList.Count) % mDataWrapList.Count;
		Refresh();
		mNpcTreasureIcon.RefleshNpcTreasureInfo(mNpcInfo.Properties.TreasureClassId);
	}

	private void OnEnterFullView()
	{
		mFullViewStates.SetState(state: true);
	}

	private void OnExitFullView()
	{
		mFullViewStates.SetState(state: false);
	}
}

}
